med=0;segmed="";div=1;nod=1;lastd="";thesed="";cat *logContra*.* | while read -r line;do thesed=${line:0:19};echo $thesed;if (( nod == 0 ));then seg=$(to_epoch2 $thesed $lastd);min=$(echo "scale=2;($seg/60)" | bc);if [[ "$segmed" != "" ]];then div=2;else segmed=0;fi;segmed=$(echo "scale=2;((${segmed} + ${seg})/${div})" | bc);minmed=$(echo "scale=2;($segmed / 60)" | bc);echo "Seg $seg Min $min SegMedios $segmed Minmed $minmed";lastd=$thesed;else lastd=$thesed;nod=0;fi;done
